pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public {
        c = new demo();
    }

    function testFuzz_property(address from, address caddress, uint256 v) public {
        address[] memory emptyTos = new address[](0);

        bool ok;
        try c.transfer(from, caddress, emptyTos, v) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference reverts on any empty _tos; the mutant (guard `>= 0`)
        // always passes and returns true, violating the rule.
        assertTrue(!ok);
    }
}
